  index=Math.max(0,Math.floor(Number(index)||0));const all=GlowportCampaign.missions,complete=index>=21;
  let target=complete?all.length:index<6?index:(GlowportCampaign.legacyMap?.[index]??6);target=clamp(target,0,all.length);
  for(let i=0;i<target;i++){const d=all[i];this.engine.state.completed[d.id]={id:d.id,title:d.title,kind:d.kind,act:d.act,run:0,runs:1,elapsed:0,failures:0,choices:{},ending:null,reward:{cash:0,reputation:0},migrated:true};this.applyFlags(d.setFlag)}
