    if(this.stack.length){const resume=this.stack.pop();if(this.engine.resume(resume.active)){this.checkpoint=resume.checkpoint;this.startCheckpoint=resume.startCheckpoint||resume.checkpoint;this.restoreCheckpoint(false)}}else if(legacy){const next=GlowportCampaign.missions.find(m=>!this.engine.state.completed[m.id]);if(next)this.engine.start(next.id)}
