 captureCheckpoint(){const p=this.api.player();return {x:p.x,y:p.y,inside:p.inside,ix:p.ix,iy:p.iy,hp:Math.max(100,p.hp),ammo:clone(p.ammo),mag:clone(p.mag),inventory:clone(this.progression.state.inventory)}}
