  const validPosition=Number.isFinite(c.x)&&Number.isFinite(c.y)&&!this.api.solid(c.x,c.y,9),fallback=this.location(this.stage()?.where);if(validPosition||fallback&&!this.api.solid(fallback.x,fallback.y,9)){p.inCar=null;p.x=validPosition?c.x:fallback.x;p.y=validPosition?c.y:fallback.y;p.inside=validPosition&&this.api.locations().some(l=>l.key===c.inside)?c.inside:null;p.ix=Number.isFinite(c.ix)?clamp(c.ix,68,730):400;p.iy=Number.isFinite(c.iy)?clamp(c.iy,78,388):377}
  p.hp=Math.max(100,Math.min(p.maxHp||150,Number(c.hp)||100));if(c.ammo&&typeof c.ammo==='object')p.ammo=clone(c.ammo);if(c.mag&&typeof c.mag==='object')p.mag=clone(c.mag);
