  if(data.routeUnavailable)return 'The objective route is unavailable.';
  if(data.points!==undefined&&(!Array.isArray(data.points)||!data.points.length||data.points.some(p=>!p||!Number.isFinite(p.x)||!Number.isFinite(p.y))))return 'The objective route is damaged.';
  if(data.goal!==undefined&&(!Number.isInteger(data.goal)||data.goal<0||data.goal>(data.points?.length||10)))return 'The objective checkpoint is damaged.';
  if(stage.type==='investigate'&&data.clue!==undefined&&(!Number.isInteger(data.clue)||data.clue<0||data.clue>(stage.clues||defaultClues).length))return 'The evidence sequence is damaged.';
  if((stage.type==='escort'&&data.picked||stage.type==='defend'&&data.spawned)&&(!this.actor||!Number.isFinite(this.actor.x)||!Number.isFinite(this.actor.y)||!Number.isFinite(this.actor.hp)))return 'Your contact is missing.';
  if(['race','drive_route'].includes(stage.type)&&this.api.player().inCar&&(this.api.player().inCar.health??100)<=0)return 'Your vehicle is disabled.';
